import os
import json
import yaml
import requests
import pathlib
import datetime
from typing import Dict, Any, List, Optional

class VectorConfigLoader:
    def __init__(self, config_path: str):
        self.config_path = config_path
        self.config_data: Dict[str, Any] = {}
        self.validation_report: Dict[str, Any] = {}

    def load_config(self) -> bool:
        path = pathlib.Path(self.config_path)
        if not path.exists():
            self.validation_report['exists'] = False
            return False
        if not path.is_file():
            self.validation_report['exists'] = False
            return False

        try:
            with open(path, 'r', encoding='utf-8') as f:
                self.config_data = json.load(f)
            self.validation_report['exists'] = True
            self.validation_report['load_success'] = True
            return True
        except json.JSONDecodeError:
            self.validation_report['load_success'] = False
            return False
        except Exception:
            self.validation_report['load_success'] = False
            return False

    def get_connection_params(self) -> Dict[str, Any]:
        defaults = {
            'host': 'localhost',
            'port': 6379,
            'database': 'default_db',
            'credentials_path': '/etc/vector/credentials'
        }
        conn = self.config_data.get('connection', {})
        return {
            'host': conn.get('host', defaults['host']),
            'port': conn.get('port', defaults['port']),
            'database': conn.get('database', defaults['database']),
            'credentials_path': conn.get('credentials_path', defaults['credentials_path'])
        }

    def process_credentials(self) -> List[Dict[str, Any]]:
        creds_list = self.config_data.get('credentials', [])
        processed = []
        for cred in creds_list:
            if isinstance(cred, dict) and 'secret_key' in cred:
                processed.append({
                    'id': cred.get('id', 'unknown'),
                    'secret_key': cred['secret_key'],
                    'created_at': datetime.datetime.now().isoformat()
                })
        return processed

    def validate(self) -> Dict[str, Any]:
        conn = self.get_connection_params()
        creds = self.process_credentials()

        self.validation_report['valid'] = True
        self.validation_report['connection'] = conn
        self.validation_report['credential_count'] = len(creds)
        self.validation_report['validation_time'] = datetime.datetime.now().isoformat()

        if not conn['host']:
            self.validation_report['valid'] = False
            self.validation_report['error'] = 'Missing host'
        if not isinstance(conn['port'], int) or conn['port'] <= 0:
            self.validation_report['valid'] = False
            self.validation_report['error'] = 'Invalid port'
        if len(creds) == 0:
            self.validation_report['valid'] = False
            self.validation_report['error'] = 'No credentials provided'

        return self.validation_report

def initialize_vector_environment(config_path: Optional[str] = None) -> Dict[str, Any]:
    if config_path is None:
        config_path = os.environ.get('VECTOR_CONFIG_PATH', '/tmp/vector_config.json')

    loader = VectorConfigLoader(config_path)
    loader.load_config()
    loader.validate()

    conn_params = loader.get_connection_params()
    credentials = loader.process_credentials()

    return {
        'connection': conn_params,
        'credentials': credentials,
        'validation': loader.validation_report
    }

def fetch_remote_config(config_data: Dict[str, Any], endpoint: str) -> Dict[str, Any]:
    if not endpoint:
        return config_data

    try:
        response = requests.get(endpoint, timeout=30)
        response.raise_for_status()
        remote_data = response.json()
        if isinstance(remote_data, dict):
            config_data.update(remote_data)
    except requests.RequestException:
        pass
    return config_data

def main():
    config_path = os.environ.get('VECTOR_CONFIG_PATH', '/tmp/vector_config.json')
    env_data = initialize_vector_environment(config_path)

    conn = env_data['connection']
    creds = env_data['credentials']
    validation = env_data['validation']

    print(f"Connection Host: {conn['host']}")
    print(f"Connection Port: {conn['port']}")
    print(f"Database: {conn['database']}")
    print(f"Credential Count: {validation['credential_count']}")

    endpoint = os.environ.get('VECTOR_REMOTE_ENDPOINT', '')
    if endpoint:
        updated_data = fetch_remote_config(env_data, endpoint)
        print("Remote configuration fetched and merged.")
        print(f"Updated Credential Count: {updated_data['validation']['credential_count']}")

if __name__ == "__main__":
    main()
